WITH loss_by_center AS ( SELECT cc.cc_call_center_id AS call_center_id, cc.cc_name AS call_center_name, sm.sm_type AS ship_mode_type, w.w_warehouse_name AS warehouse_name, cc.cc_employees AS employee_count, COUNT(*) AS return_cnt, SUM(cr.cr_net_loss) AS total_net_loss, AVG(cr.cr_net_loss) AS avg_net_loss FROM catalog_returns cr JOIN call_center cc ON cr.cr_call_center_sk = cc.cc_call_center_sk JOIN ship_mode sm ON cr.cr_ship_mode_sk = sm.sm_ship_mode_sk JOIN warehouse w ON cr.cr_warehouse_sk = w.w_warehouse_sk GROUP BY cc.cc_call_center_id, cc.cc_name, sm.sm_type, w.w_warehouse_name, cc.cc_employees ) SELECT call_center_id, call_center_name, ship_mode_type, warehouse_name, employee_count, return_cnt, avg_net_loss, ROW_NUMBER() OVER (PARTITION BY ship_mode_type ORDER BY avg_net_loss DESC) AS rn FROM loss_by_center WHERE avg_net_loss > 50 AND return_cnt >= 3 ORDER BY ship_mode_type, avg_net_loss DESC
